/// <summary>
/// in AX2009 NDX_UmsatzClassBatch
/// </summary>
class NDXUmsatzRefreshClass
{
    NoYes                       lThread;
    boolean                     lBuildAlliance;
    boolean                     lBuildSalesGroup;
    NoYes                       lBuildVerband;
    NoYes                       lBuildAll;
    NoYes                       lLiveSales;
    NoYes                       lfillKumUmsCust;
    NoYes                       lCheckKumUmsCust;
    CustAccount                 alliance;
    CommissSalesGroup           salesGroup;
    Version                     dataVersion;
    NDXMonthBE                  liveSalesMonth;
    NDXYear                     liveSalesYear;
    boolean                     lisBatch;
    NDXUmsatzCSRefreshContract nDXUmsatzCSRefreshContract;
    NDXMultiThreadingCreateTaskUmsLJController nDXMultiThreadingCreateTaskUmsLJController;
    NDXMultiThreadingCreateTaskUmsVJController nDXMultiThreadingCreateTaskUmsVJController;
    NDXSignature signatureUmsLJ;
    NDXSignature signatureUmsVJ;

}

Method.Source:
/// <summary>
/// PaffH 20.01.25
/// </summary>
protected void new()
{
    signatureUmsLJ = NDXHelperCommon::Signature();
    signatureUmsVJ = NDXHelperCommon::Signature();
}

/// <summary>
/// PaffH 20.01.25
/// </summary>
/// <returns>NDXUmsatzRefreshClass</returns>
public static NDXUmsatzRefreshClass construct()
{
    NDXUmsatzRefreshClass nDXUmsatzRefreshClass = new NDXUmsatzRefreshClass();
    return nDXUmsatzRefreshClass;
}

/// <summary>
/// PaffH 20.01.25
/// </summary>
/// <param name = "_contract">NDXUmsatzCSRefreshContract</param>
/// <returns>NDXUmsatzRefreshClass</returns>
public static NDXUmsatzRefreshClass constructFromContract(NDXUmsatzCSRefreshContract _contract)
{
    NDXUmsatzRefreshClass nDXUmsatzRefreshClass = new NDXUmsatzRefreshClass();
    nDXUmsatzRefreshClass.nDXUmsatzCSRefreshContract = _contract;
    if (_contract.parmBatchWithMultithreading() == NoYes::Yes)  // #NDXBatchMultiThreading
    {
        NDXBatchMultiThreadingContract batchMultiThreadingContract = NDXBatchMultiThreadingContract::construct();
        batchMultiThreadingContract.parmSysOperationExecutionMode(SysOperationExecutionMode::ReliableAsynchronous);

        batchMultiThreadingContract.parmSignature(nDXUmsatzRefreshClass.signatureUmsLJ);
        batchMultiThreadingContract.parmUmsBasisLJ(true);
        batchMultiThreadingContract.parmSignatureUmsVJ(nDXUmsatzRefreshClass.signatureUmsVJ);
        NDXMultiThreadingCreateTaskUmsController controller = NDXMultiThreadingCreateTaskUmsController::instance(batchMultiThreadingContract);
        //NDXMultiThreadingCreateTaskContract contract = controller.getDataContractObject('_contract');
        //if (!contract)
        //{
        //    throw Error(strFmt("@SYS23264", classStr(NDXMultiThreadingCreateTaskContract)));
        //}
        //contract.parmUmsBasisLJ(batchMultiThreadingContract.parmUmsBasisLJ());
        //contract.parmSignatureUmsVJ(batchMultiThreadingContract.parmSignatureVJ());
        nDXUmsatzRefreshClass.parmNDXMultiThreadingCreateTaskUmsLJController(controller);

        batchMultiThreadingContract.parmSignature(nDXUmsatzRefreshClass.signatureUmsVJ);
        batchMultiThreadingContract.parmUmsBasisLJ(false);
        controller = NDXMultiThreadingCreateTaskUmsController::instance(batchMultiThreadingContract);
        //contract = controller.getDataContractObject('_contract');
        //if (!contract)
        //{
        //    throw Error(strFmt("@SYS23264", classStr(NDXMultiThreadingCreateTaskContract)));
        //}
        //contract.parmUmsBasisLJ(batchMultiThreadingContract.parmUmsBasisLJ());
        //contract.parmSignatureUmsVJ(batchMultiThreadingContract.parmSignatureVJ());
        nDXUmsatzRefreshClass.parmNDXMultiThreadingCreateTaskUmsVJController(controller);
    }
    return nDXUmsatzRefreshClass;
}

/// <summary>
/// PaffH 24.01.25
/// </summary>
/// <param name = "_nDXMultiThreadingCreateTaskUmsLJController">NDXMultiThreadingCreateTaskUmsLJController</param>
/// <returns>nDXMultiThreadingCreateTaskUmsLJController</returns>
public NDXMultiThreadingCreateTaskUmsLJController parmNDXMultiThreadingCreateTaskUmsLJController(NDXMultiThreadingCreateTaskController _nDXMultiThreadingCreateTaskUmsLJController = nDXMultiThreadingCreateTaskUmsLJController)
{
    nDXMultiThreadingCreateTaskUmsLJController = _nDXMultiThreadingCreateTaskUmsLJController;
    return nDXMultiThreadingCreateTaskUmsLJController;
}

/// <summary>
/// PaffH 24.01.25
/// </summary>
/// <param name = "_nDXMultiThreadingCreateTaskUmsVJController">NDXMultiThreadingCreateTaskUmsVJController</param>
/// <returns>nDXMultiThreadingCreateTaskUmsVJController</returns>
public NDXMultiThreadingCreateTaskUmsVJController parmNDXMultiThreadingCreateTaskUmsVJController(NDXMultiThreadingCreateTaskController _nDXMultiThreadingCreateTaskUmsVJController = nDXMultiThreadingCreateTaskUmsVJController)
{
    nDXMultiThreadingCreateTaskUmsVJController = _nDXMultiThreadingCreateTaskUmsVJController;
    return nDXMultiThreadingCreateTaskUmsVJController;
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
public void run()
{

    NDXJobMangerJobsClass  nDX_JobManagerJobs;

    NDXUmsatzClassArgs      args;
    str                     s_Date;
    InvoiceDate             l_Date, dateFrom, dateTo;
    int                     nCounter;

    nDX_JobManagerJobs = NDXJobMangerJobsClass::construct(NDXJobManagerJobId::getUms);
    //TODO: DebuC austauschen der Winapi durch Protokolltabelle
    nDX_JobManagerJobs.openFileToWrite(true);
    nDX_JobManagerJobs.start();

    if (lLiveSales || lfillKumUmsCust)
    {
        s_Date      = strfmt('01/%1/%2', enum2int(liveSalesMonth), liveSalesYear);
        l_Date      = str2date(s_Date, 123);
        dateFrom    = DateStartMth(l_Date);
        dateto      = DateEndMth(l_Date);
        if (lLiveSales)
        {
            ++nCounter;

            nDX_JobManagerJobs.setAction('NXD4262', strfmt('%1-%2', dateFrom, dateTo), nCounter);          
            // Live-Umsatzdaten verarbeiten                
            NDXUmsatzClass::fillLiveSales(dateFrom, dateTo);
        }
        if (lfillKumUmsCust)
        {
            ++nCounter;

            nDX_JobManagerJobs.setAction('NXD4268', '', nCounter);             
            // Kunden mit Verkäufen prüfen
            NDXKumUmsCustWithSales::CheckCustWithSales();
            ++nCounter;

            nDX_JobManagerJobs.setAction('NXD4269', strfmt('%1.%2', liveSalesMonth, liveSalesYear), nCounter);         
            // KumUmsCust aus LiveSales füllen
            NDXUmsatzClass::fillNDXKumUmsCustFromLiveSales(liveSalesMonth, liveSalesYear, lCheckKumUmsCust);
            ++nCounter;

            nDX_JobManagerJobs.setAction('NXD4270', strfmt('%1.%2', liveSalesMonth, liveSalesYear), nCounter);         
            // KumUmsCustArtGrp aus LiveSales füllen
            NDXUmsatzClass::fillNDXKumUmsCustArtGrpFromLiveSales(liveSalesMonth, liveSalesYear, lCheckKumUmsCust);
        }
    }

    args = NDXUmsatzClassArgs::construct();
    args.parmLisBatch(lisBatch);
    args.parmlThread(lThread);
    args.parmlBuildVerband(lBuildVerband);
    args.parmDataVersion(dataVersion);
    args.parmlGetLastValues(NDXNoYesBE::No);           // keine LastValues ermitteln
    args.parmlCSIncl(NDXNoYesBE::Yes);                 // Zentrallagerverteilung einbeziehen
    args.parmBatchWithMultithreading(nDXUmsatzCSRefreshContract.parmBatchWithMultithreading());
    if (lBuildAll)      // Verband und Verkaufsbereich komplett neu bilden
    {
        //Verband incl. MasterAlliance
        args.parmDataVersion(NDXUmsatzConstants::DataVersionVerband);
        args.parmlBuildVerband(true);
        ++nCounter;

        nDX_JobManagerJobs.setAction('NXD4267', '', nCounter);             
        // Verband incl. MasterAlliance
        NDXUmsatzClass::FillCSStatistikData(args);

        //Verkaufsbereich
        args.parmDataVersion(NDXUmsatzConstants::DataVersionVKBereich);
        args.parmlBuildVerband(false);
        args.parmMaster('');
        args.parmSalesGroupId(NDXUmsatzConstants::all);
        args.parmlSalesGroupMaster(true);
        ++nCounter;

        nDX_JobManagerJobs.setAction('SYS105802', '', nCounter);               
        // Verkaufsbereich
        NDXUmsatzClass::FillCSStatistikData(args);
    }
    else if (lBuildAlliance)                    // einen oder alle Verbände neu bilden
    {
        args.parmDataVersion(NDXUmsatzConstants::DataVersionVerband);
        // für aktuelles Jahr
        args.parmlBasisUmsLfdJ(NDXNoYesBE::Yes);
        args.parmMaster(alliance);
        ++nCounter;

        nDX_JobManagerJobs.setAction('NXD4266', '', nCounter);             
        // Verbände aktuelles Jahr
        NDXUmsatzClass::FillCSStatistikData(args);
        // für Vorjahr
        args.parmlBasisUmsLfdJ(NDXNoYesBE::No);
        args.parmlBuildVerband(false);
        ++nCounter;

        nDX_JobManagerJobs.setAction('NXD4265', '', nCounter);             
        // Verbände Vorjahr
        NDXUmsatzClass::FillCSStatistikData(args);

        // #NDXBatchMultiThreading
        if (args.parmBatchWithMultithreading() == NoYes::Yes)    
        {
            runAsync(classNum(NDXBatchMultithreadingSalesConsolidation),
            staticMethodStr(NDXBatchMultithreadingSalesConsolidation, runNDXMultiThreadingCreateTaskController),
                [false, SysOperationExecutionMode::ReliableAsynchronous, signatureUmsLJ, signatureUmsVJ, NDXNoYesBE::Yes],
            System.Threading.CancellationToken::None,
            classNum(NDXBatchMultithreading),
            staticMethodStr(NDXBatchMultithreading, callBackrunNDXMultiThreadingCreateTaskController));

            //runAsync(classNum(NDXBatchMultithreadingSalesConsolidation),
            //staticMethodStr(NDXBatchMultithreadingSalesConsolidation, runNDXMultiThreadingCreateTaskController),
            //[false, SysOperationExecutionMode::ReliableAsynchronous, signatureUmsVJ, NDXNoYesBE::No],
            //System.Threading.CancellationToken::None,
            //classNum(NDXBatchMultithreading),
            //staticMethodStr(NDXBatchMultithreading, callBackrunNDXMultiThreadingCreateTaskController));
        }


    }
    else if (lBuildSalesGroup)                  // einen oder alle Verkaufsbereiche neu bilden
    {
        args.parmDataVersion(NDXUmsatzConstants::DataVersionVKBereich);
        args.parmMaster('');
        args.parmSalesGroupId(salesGroup ? salesGroup : NDXUmsatzConstants::all);
        args.parmlSalesGroupMaster(true);

        // für aktuelles Jahr
        args.parmlBasisUmsLfdJ(NDXNoYesBE::Yes);
        ++nCounter;

        nDX_JobManagerJobs.setAction('NXD4264', '', nCounter);         
        // Verkaufsbereiche aktuelles Jahr
        NDXUmsatzClass::FillCSStatistikData(args);

        // für Vorjahr
        args.parmlBuildVerband(false);
        args.parmlBasisUmsLfdJ(NDXNoYesBE::No);
        ++nCounter;

        nDX_JobManagerJobs.setAction('NXD4263', '', nCounter);         
        // Verkaufsbereiche Vorjahr
        NDXUmsatzClass::FillCSStatistikData(args);
    } 

    nDX_JobManagerJobs.ende(nCounter);
}

CommissSalesGroup parmSalesGroup(CommissSalesGroup l_salesGroup = salesGroup)
{
    ;
    if (!prmisdefault(l_salesGroup))
    {
        this.parmLBuildSalesGroup(l_salesGroup > '');
    }

    salesGroup = l_salesGroup;
    return salesGroup;
}

boolean parmlisBatch(boolean l_isBatch = lisBatch)
{
    ;
    if (!prmisdefault(l_isBatch))
    {
        lisBatch = l_isBatch;
    }

    return lisBatch;
}

version parmDataVersion(Version l_dataVersion = dataVersion)
{
    dataVersion = l_dataVersion;
    return dataVersion;
}

boolean parmLBuildSalesGroup(boolean l_lBuildSalesGroup = lBuildSalesGroup)
{
    ;
    lBuildSalesGroup    = l_lBuildSalesGroup;
    lBuildAlliance      = !lBuildSalesGroup;
    return lBuildSalesGroup;
}

boolean parmLBuildAlliance(boolean l_lBuildAlliance = lBuildAlliance)
{
    ;
    lBuildAlliance      = l_lBuildAlliance;
    lBuildSalesGroup    = !lBuildAlliance;
    return lBuildAlliance;
}

CustAccount parmAlliance(CustAccount l_alliance = alliance)
{
    ;
    if (!prmisdefault(l_alliance))
    {
        this.parmLBuildAlliance(l_alliance > '');
    }

    alliance = l_alliance;
    return alliance;
}

NoYes parmLBuildVerband(NoYes l_lBuildVerband = lBuildVerband)
{
    ;
    lBuildVerband   = l_lBuildVerband;
    return lBuildVerband;
}

NoYes parmLBuildAll(NoYes l_lBuildAll = lBuildAll)
{
    ;
    lBuildAll   = l_lBuildAll;
    return lBuildAll;
}

NoYes parmlCheckKumUmsCust(NoYes l_lCheckKumUmsCust = lCheckKumUmsCust)
{
    lCheckKumUmsCust = l_lCheckKumUmsCust;
    return lCheckKumUmsCust;
}

NoYes parmlfillKumUmsCust(NoYes l_lfillKumUmsCust = lfillKumUmsCust)
{
    lfillKumUmsCust = l_lfillKumUmsCust;
    return lfillKumUmsCust;
}

NDXMonthBE parmLiveSalesMonth(NDXMonthBE l_liveSalesMonth = liveSalesMonth)
{
    ;
    liveSalesMonth  = l_liveSalesMonth;
    return liveSalesMonth;
}

NDXYear parmLiveSalesYear(NDXYear l_liveSalesYear = liveSalesYear)
{
    ;
    liveSalesYear  = l_liveSalesYear;
    return liveSalesYear;
}

NoYes parmlLiveSales(NoYes l_lLiveSales = lLiveSales)
{
    lLiveSales = l_lLiveSales;
    return lLiveSales;
}

NoYes parmLThread(NoYes l_lThread = lThread)
{
    ;
    lThread   = l_lThread;
    return lThread;
}
